import numpy as np,sys
f=sys.argv[1]
L=open(f).read().split('\n')[2:]
at=[(l.split()[0],np.array(list(map(float,l.split()[1:4])))) for l in L if l.strip()]
def d(i,j): return np.linalg.norm(at[i][1]-at[j][1])
print('Mo-Oc',d(1,0),'Na-Oc',d(2,0))
print('Mo-N',d(1,39),'N-O',d(39,40),'Na-O(MeOH)',d(2,41),'O-C MeOH',d(41,42))
for i in [12,14,16,18]: print('Na-Olac',d(2,i))
for i in [19,24,29,34]: print('Mo-OMe',d(1,i),'W-OMe',min(d(i,w) for w in range(3,7)),'O-C',d(i,i+1))
for i in [11,13,15,17]: print('W=O',min(d(i,w) for w in range(3,7)))
